import React, { useState, useRef, useEffect } from "react";
import axios from "axios";
import QRCode from "react-qr-code";
import { useLocation } from "react-router-dom";
import Navbar from "./Navbar";
import html2canvas from "html2canvas";
import * as faceapi from "face-api.js";

function Register() {
  const location = useLocation();

const eventId = location.state?.eventId;
const eventName = location.state?.eventName;

  const [formData, setFormData] = useState({
    name: "",
    college_name: "",
    phone: "",
    event_id: "",
  });

  const [qrData, setQrData] = useState("");
  const [userId, setUserId] = useState("");
  const [photo, setPhoto] = useState(null);

  const [faceDetected, setFaceDetected] = useState(false);
  const [modelsLoaded, setModelsLoaded] = useState(false);

  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const idCardRef = useRef(null);
  const streamRef = useRef(null);

  /* =============================
      SET EVENT FROM URL
  ============================= */

 useEffect(() => {

  if (eventId) {

    setFormData((prev) => ({
      ...prev,
      event_id: eventId
    }));

  }

}, [eventId]);
  /* =============================
      LOAD FACE MODEL
  ============================= */

  useEffect(() => {
    const loadModels = async () => {
      try {
        await faceapi.nets.tinyFaceDetector.loadFromUri("/models");

        setModelsLoaded(true);

        console.log("Face model loaded");
      } catch (error) {
        console.log("Model error:", error);
      }
    };

    loadModels();
  }, []);

  /* =============================
      INPUT CHANGE
  ============================= */

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  /* =============================
      REGISTER USER
  ============================= */

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const res = await axios.post("http://localhost:5000/register", formData);

      setQrData(res.data.qrData);
      setUserId(res.data.userId);

      alert("Registration Successful");
    } catch (error) {
      console.log(error);

      alert("Registration Failed");
    }
  };

  /* =============================
      OPEN CAMERA
  ============================= */

  const openCamera = async () => {
    if (!modelsLoaded) {
      alert("Face model still loading...");

      return;
    }

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: true,
      });

      videoRef.current.srcObject = stream;
      streamRef.current = stream;

      videoRef.current.onloadedmetadata = () => {
        videoRef.current.play();

        detectFace();
      };
    } catch {
      alert("Camera access denied");
    }
  };

  /* =============================
      FACE DETECTION
  ============================= */

  const detectFace = async () => {
    if (!videoRef.current) return;

    const detections = await faceapi.detectAllFaces(
      videoRef.current,
      new faceapi.TinyFaceDetectorOptions(),
    );

    if (detections.length === 1) {
      setFaceDetected(true);
    } else {
      setFaceDetected(false);
    }

    setTimeout(detectFace, 500);
  };

  /* =============================
      CAPTURE PHOTO
  ============================= */

  const capturePhoto = () => {
    const canvas = canvasRef.current;
    const video = videoRef.current;

    const ctx = canvas.getContext("2d");

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    ctx.drawImage(video, 0, 0);

    const image = canvas.toDataURL("image/png");

    setPhoto(image);

    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
    }
  };

  /* =============================
      DOWNLOAD ID CARD
  ============================= */

  const downloadCard = () => {
    html2canvas(idCardRef.current).then((canvas) => {
      const link = document.createElement("a");

      link.download = "IDCard.png";

      link.href = canvas.toDataURL();

      link.click();
    });
  };

  const eventNames = {
    1: "Technical Event",
    2: "24 Hour Hackathon",
    3: "Coding Contest",
    4: "Cultural Event",
  };

  return (
    <div>
      <Navbar />

      <div style={{ padding: "20px" }}>
        <h2>SympoTech Event Registration</h2>

        {/* REGISTER FORM */}

        <form onSubmit={handleSubmit}>
          <input
            name="name"
            placeholder="Name"
            onChange={handleChange}
            required
          />

          <br />
          <br />

          <input
            name="college_name"
            placeholder="College Name"
            onChange={handleChange}
            required
          />

          <br />
          <br />

          <input
            name="phone"
            placeholder="Phone Number"
            onChange={handleChange}
            required
          />

          <br />
          <br />

              

<h3>Selected Event : {eventName}</h3>

          <br />
          <br />

          <button type="submit">Register</button>
        </form>

        

        {/* QR CODE + CAMERA */}

        {qrData && (
          <div>
            <h3>Your QR Code</h3>

            <QRCode value={qrData} size={120} />

            <h3>Take Photo</h3>

            <button onClick={openCamera}>Open Camera</button>

            <br />
            <br />

            <video
              ref={videoRef}
              autoPlay
              playsInline
              width="300"
              height="200"
              style={{ border: "2px solid black" }}
            />

            <br />

            {faceDetected ? (
              <p style={{ color: "green" }}>One Face Detected</p>
            ) : (
              <p style={{ color: "red" }}>No Face / Multiple Faces</p>
            )}

            <button onClick={capturePhoto} disabled={!faceDetected}>
              Capture Photo
            </button>

            <canvas ref={canvasRef} style={{ display: "none" }} />
          </div>
        )}

        {/* ID CARD */}

        {photo && (
          <div>
            <div
              ref={idCardRef}
              style={{
                border: "2px solid black",
                width: "300px",
                padding: "10px",
                marginTop: "20px",
              }}
            >
              <h3>College Event ID Card</h3>

              <p>Name: {formData.name}</p>

              <p>User ID: {userId}</p>

              <p>Event: {eventNames[formData.event_id]}</p>

              <QRCode value={qrData} size={100} />

              <br />
              <br />

              <img src={photo} alt="user" width="120" />
            </div>

            <br />

            <button onClick={downloadCard}>Download ID Card</button>
          </div>
        )}
      </div>
    </div>
  );
}

export default Register;
